def seed_footer_pages(apps, schema_editor):
    FooterPage = apps.get_model("footer_pages", "FooterPage")

    for page_data in FOOTER_PAGES:
        existing_page = FooterPage.objects.filter(
            Q(key=page_data["key"]) | Q(slug=page_data["slug"])
        ).first()

        if existing_page:
            for field, value in page_data.items():
                setattr(existing_page, field, value)
            existing_page.save(
                update_fields=["key", "slug", "title", "content", "is_published", "updated_at"]
            )
            continue

        FooterPage.objects.create(**page_data)


